def consolidate_access_menu(apps, schema_editor):
    MenuItem = apps.get_model('cms_adp', 'MenuItem')

    permissions_item = MenuItem.objects.filter(route_name='PermissionsPanel').first()
    limitations_item = MenuItem.objects.filter(route_name='LiminationPanel').first()

    preserved_order = None
    preserved_parent = None

    if permissions_item is not None:
        preserved_order = permissions_item.order
        preserved_parent = permissions_item.parent
        permissions_item.name = 'Управление доступом'
        permissions_item.route_name = NEW_ROUTE_NAME
        permissions_item.save(update_fields=['name', 'route_name'])
    elif limitations_item is not None:
        preserved_order = limitations_item.order
        preserved_parent = limitations_item.parent
        limitations_item.name = 'Управление доступом'
        limitations_item.route_name = NEW_ROUTE_NAME
        limitations_item.save(update_fields=['name', 'route_name'])

    MenuItem.objects.filter(
        route_name__in=['LiminationPanel', 'ModulePagePermissionsPanel'],
    ).delete()

    admin_panel = MenuItem.objects.filter(route_name='AdminPanel').first()
    parent = preserved_parent or admin_panel

    if parent is not None and not MenuItem.objects.filter(route_name=NEW_ROUTE_NAME).exists():
        from django.db.models import Max

        max_order = MenuItem.objects.filter(parent=parent).aggregate(
            Max('order'),
        )['order__max'] or 0

        MenuItem.objects.create(
            name='Управление доступом',
            route_name=NEW_ROUTE_NAME,
            icon='Shield',
            item_type='route',
            parent=parent,
            order=preserved_order if preserved_order is not None else max_order + 10,
            is_active=True,
            is_admin_only=True,
            module_source='core/cms',
        )


def restore_access_menu(apps, schema_editor):
    MenuItem = apps.get_model('cms_adp', 'MenuItem')

    access_item = MenuItem.objects.filter(route_name=NEW_ROUTE_NAME).first()
    if access_item is None:
        return

    access_item.name = 'Управление доступом'
    access_item.route_name = 'PermissionsPanel'
    access_item.save(update_fields=['name', 'route_name'])

    admin_panel = access_item.parent
    if admin_panel is None:
        return

    if not MenuItem.objects.filter(route_name='LiminationPanel').exists():
        MenuItem.objects.create(
            name='Ограничения',
            route_name='LiminationPanel',
            icon='Lock',
            item_type='route',
            parent=admin_panel,
            order=access_item.order + 10,
            is_active=True,
            is_admin_only=True,
            module_source='core/cms',
        )


def ensure_user_extension_columns(apps, schema_editor):
    from django.contrib.auth import get_user_model
    from django.db import connection

    vendor = connection.vendor
    table_name = get_user_model()._meta.db_table

    with connection.cursor() as cursor:
        _add_column_if_missing(
            cursor,
            vendor,
            table_name,
            'middle_name',
            'VARCHAR(150) NULL',
        )
        public_id_sql = 'TEXT NULL' if vendor == 'sqlite' else 'UUID NULL'
        _add_column_if_missing(
            cursor,
            vendor,
            table_name,
            'public_id',
            public_id_sql,
        )

        if vendor == 'postgresql':
            cursor.execute(
                f'CREATE UNIQUE INDEX IF NOT EXISTS auth_user_public_id_uniq ON "{table_name}" (public_id)'
            )
            cursor.execute(
                f'UPDATE "{table_name}" SET public_id = gen_random_uuid() WHERE public_id IS NULL'
            )
        else:
            cursor.execute(f'SELECT id FROM "{table_name}" WHERE public_id IS NULL')
            for (user_id,) in cursor.fetchall():
                cursor.execute(
                    f'UPDATE "{table_name}" SET public_id = %s WHERE id = %s',
                    [str(uuid.uuid4()), user_id],
                )


def noop_reverse(apps, schema_editor):
    pass


def remove_fork_auth_migration_records(apps, schema_editor):
    from django.db import connection

    placeholders = ', '.join(['%s'] * len(FORK_AUTH_MIGRATIONS))
    with connection.cursor() as cursor:
        cursor.execute(
            f'DELETE FROM django_migrations WHERE app = %s AND name IN ({placeholders})',
            ['auth', *FORK_AUTH_MIGRATIONS],
        )


def migrate_user_content_type(apps, schema_editor):
    ContentType = apps.get_model('contenttypes', 'ContentType')
    Permission = apps.get_model('auth', 'Permission')

    old_ct = ContentType.objects.filter(app_label='auth', model='user').first()
    new_ct, _ = ContentType.objects.get_or_create(
        app_label='cms_adp',
        model='ergouser',
    )

    if old_ct is None:
        return

    if old_ct.pk != new_ct.pk:
        Permission.objects.filter(content_type_id=old_ct.pk).update(content_type_id=new_ct.pk)
        old_ct.delete()
    else:
        old_ct.app_label = 'cms_adp'
        old_ct.model = 'ergouser'
        old_ct.save(update_fields=['app_label', 'model'])


